const INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"theme-color\" content=\"#faf8f6\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>InfiniRoll</title>\n<meta name=\"description\" content=\"Roll a number from 0 to 1 000 000, collect 233 badges and climb the leaderboard.\">\n<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@500;700;800&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--bg:#faf8f6;--card:#fff;--line:#ece7e2;--txt:#1c1917;--dim:#8a817a;--sub:#57534e;--soft:#f5f5f4;--hl:#fdf4ff;--acc:#ea580c;--acc2:#c2410c;--accfg:#fff;--accsoft:#fff7ed;--accline:#fdba74;--acctext:#9a3412;--or:#f59e0b;--or2:#9a3412;--blue:#3b82f6;color-scheme:light}\nbody,.mbox,.lb,.adm,.ci,.bcard{transition:background-color .25s,color .25s,border-color .25s}\ninput{background:var(--card);color:var(--txt)}\n*{box-sizing:border-box;margin:0;padding:0}\nbody{background:var(--bg);color:var(--txt);font-family:Inter,sans-serif;min-height:100vh}\n.top{display:flex;align-items:center;gap:18px;padding:14px 20px;flex-wrap:wrap}\n.brand{font:800 20px 'JetBrains Mono',monospace;letter-spacing:1px}\n.brand span{color:var(--acc)}\n.top .lnk{font-size:12px;font-weight:600;color:var(--dim);cursor:pointer;text-transform:uppercase;letter-spacing:.5px;background:none;border:none}\n.top .lnk.on{color:var(--txt)}\n.main{max-width:660px;margin:0 auto;padding:20px 16px 60px;display:flex;flex-direction:column;align-items:center}\n.numbox{border:3px solid var(--accline);background:var(--accsoft);border-radius:16px;padding:18px 34px;min-width:220px;text-align:center;box-shadow:0 6px 30px color-mix(in srgb,var(--acc) 20%,transparent);transition:border-color .3s,box-shadow .3s}\n.num{font:800 64px 'JetBrains Mono',monospace;color:var(--or2);letter-spacing:2px;line-height:1.1;word-break:break-all}\n.numbox.spin .num{color:var(--dim)!important;opacity:.6}\n.num{color:var(--acctext)}\n.tierline{margin-top:16px;display:flex;align-items:center;gap:12px;font-size:14px;font-weight:600}\n.tag{border:1.5px solid currentColor;border-radius:5px;padding:3px 9px;font-size:13px;font-weight:700;letter-spacing:.5px;text-transform:uppercase}\n.dot{width:4px;height:4px;border-radius:50%;background:var(--dim)}\n.ep{margin-top:14px;font:800 16px 'JetBrains Mono',monospace;color:var(--acctext);border:1.5px solid var(--accline);background:var(--accsoft);border-radius:999px;padding:6px 14px}\n.life{margin-top:10px;font:700 15px 'JetBrains Mono',monospace;text-align:center}\n.life small{display:block;font:500 12px Inter;color:var(--dim);text-transform:uppercase;margin-top:2px}\n.actions{display:flex;gap:10px;align-items:center;margin-top:18px;flex-wrap:wrap;justify-content:center}\n.btn{font:700 14px Inter;border:1.5px solid var(--line);background:var(--card);border-radius:10px;padding:10px 16px;cursor:pointer;text-transform:uppercase;letter-spacing:.5px;color:var(--txt)}\n.btn:active{transform:scale(.97)}\n.btn.roll{background:linear-gradient(135deg,var(--acc),var(--acc2));color:var(--accfg);border:none;padding:13px 30px;font-size:16px;box-shadow:0 4px 18px color-mix(in srgb,var(--acc) 30%,transparent)}\n.btn.roll:disabled{opacity:.5}\n.btn.on{background:#16a34a;color:#fff;border-color:#16a34a}\n.hint{font-size:12px;color:var(--dim);margin-top:10px}\nh3{margin-top:34px;font-size:20px;font-weight:800;text-transform:uppercase;text-align:center}\n.h3s{font-size:12px;font-weight:600;text-transform:uppercase;color:var(--sub);text-align:center;margin-top:2px}\n.list{width:100%;margin-top:14px;display:flex;flex-direction:column;gap:12px}\n.bcard{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px;box-shadow:0 1px 3px #0000000a;animation:in .3s both}\n@keyframes in{from{opacity:0;transform:translateY(6px)}}\n.bhead{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.bname{font-weight:700;font-size:14px;text-transform:uppercase}\n.rar{font-size:11px;font-weight:700;border:1.5px solid currentColor;border-radius:5px;padding:2px 6px;text-transform:uppercase}\n.bep{margin-left:auto;font:700 12px 'JetBrains Mono',monospace;color:var(--acctext);background:var(--accsoft);border:1.5px solid var(--accline);border-radius:999px;padding:3px 9px}\n.bdesc{font-size:12px;color:var(--dim);text-transform:uppercase;margin-top:6px;padding-bottom:10px;border-bottom:1px solid var(--line)}\n.digits{display:flex;gap:4px;margin-top:10px;flex-wrap:wrap}\n.d{width:20px;height:24px;border-radius:4px;display:flex;align-items:center;justify-content:center;font:700 12px 'JetBrains Mono',monospace;color:var(--dim);background:var(--soft)}\n.d.a{background:#93c5fd;border:1.5px solid #3b82f6;color:#1e3a8a}\n.d.b{background:#86efac;border:1.5px solid #22c55e;color:#14532d}\n.empty{color:var(--dim);font-size:14px;text-align:center;padding:20px}\n.row{display:flex;align-items:center;gap:12px;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 14px}\n.row .rk{font:800 14px 'JetBrains Mono',monospace;width:28px;color:var(--dim)}\n.row .rn{font:800 18px 'JetBrains Mono',monospace;color:var(--or2);flex:1;word-break:break-all}\n.row .re{font:700 13px 'JetBrains Mono',monospace;color:#c2410c}\n.coll{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:8px;width:100%;margin-top:14px}\n.ci{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px;font-size:12px}\n.ci b{display:block;font-size:13px;text-transform:uppercase;margin-bottom:4px}\n.ci.lock{opacity:.4}\n.ci .meta{display:flex;justify-content:space-between;color:var(--dim);margin-top:6px;font-family:'JetBrains Mono',monospace}\n.toast{position:fixed;bottom:20px;left:50%;transform:translateX(-50%);background:#1c1917;color:#fff;padding:10px 18px;border-radius:10px;font-size:14px;opacity:0;transition:opacity .3s;pointer-events:none;z-index:9}\n.toast.show{opacity:1}\n.calib{position:fixed;inset:0;background:var(--bg);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:10px;z-index:8;font-weight:600;color:var(--dim)}\n.rainbow{background:linear-gradient(90deg,#ef4444,#f59e0b,#22c55e,#3b82f6,#a855f7,#ef4444);background-size:300%;-webkit-background-clip:text;background-clip:text;color:transparent!important;border-color:#a855f7!important;animation:rb 2s linear infinite}\n@keyframes rb{to{background-position:300%}}\n.pop{animation:pop .45s cubic-bezier(.2,1.6,.4,1)}\n@keyframes pop{0%{transform:scale(.85)}100%{transform:scale(1)}}\n.cut{position:fixed;inset:0;z-index:10;display:none;flex-direction:column;align-items:center;justify-content:center;background:#0c0a09f0;color:#fff;text-align:center;cursor:pointer}\n.cut.show{display:flex;animation:fade .3s}\n@keyframes fade{from{opacity:0}}\n.cutTier{font:800 22px Inter;letter-spacing:6px;text-transform:uppercase}\n.cutNum{font:800 min(18vw,120px) 'JetBrains Mono',monospace;margin-top:10px;animation:zoom 1.1s cubic-bezier(.2,1.5,.4,1)}\n@keyframes zoom{0%{transform:scale(.2);opacity:0;filter:blur(12px)}100%{transform:none;opacity:1;filter:none}}\n.cutSub{font:600 16px 'JetBrains Mono',monospace;margin-top:14px;opacity:.85}\n.cutHint{margin-top:34px;font-size:12px;opacity:.5}\n.rarity{background:#1c1917;color:#e7e5e4;border-radius:16px;padding:26px 28px}\n.rarity h2{font-size:26px;font-weight:800;color:#fff;margin-bottom:18px}\n.rarity h4{font-size:15px;font-weight:800;text-transform:uppercase;color:#fff;margin-bottom:8px}\n.rarity p{font-size:14px;line-height:1.5;color:#d6d3d1;margin-bottom:14px}\n.rgrid{display:grid;grid-template-columns:1fr 1fr;gap:28px}\n@media(max-width:600px){.rgrid{grid-template-columns:1fr}}\n.rt{display:grid;grid-template-columns:110px 1fr;row-gap:12px;font-size:13px}\n.rt .n{font-weight:600;text-transform:uppercase}\n.rt .v{color:#a8a29e;font-size:11px;text-transform:uppercase;align-self:center}\n.rarity .note{margin:22px 0 0;font-size:12px;color:#a8a29e}\n.rarity .note b{color:#fff}\n.lb{width:100%;background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden}\n.lbtabs{display:flex;border-bottom:1px solid var(--line)}\n.lbtabs button{flex:1;background:none;border:none;padding:13px 6px;font:700 12px Inter;letter-spacing:.5px;text-transform:uppercase;color:var(--dim);cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-1px}\n.lbtabs button.on{color:var(--txt);border-bottom-color:var(--txt)}\n.lbme{padding:10px 16px;font-size:13px;color:var(--dim);border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n.lbme:empty{display:none}\n.lbme .btn{padding:6px 12px;font-size:12px}\n.lrow{display:grid;grid-template-columns:44px 1fr auto auto auto;align-items:center;gap:0 14px;padding:12px 16px;border-bottom:1px solid var(--line)}\n.lrow.me{background:var(--hl)}\n.lrank{font:800 13px 'JetBrains Mono',monospace;text-align:left}\n.lrank.medal{font-size:20px}\n.lname{font:800 16px Inter;text-transform:uppercase;letter-spacing:.3px;word-break:break-all}\n.lname .em{margin-left:6px;font-size:15px}\n.lmotto{grid-column:2/-1;font:500 13px 'JetBrains Mono',monospace;color:var(--sub);margin-top:6px;word-break:break-word}\n.lnum{font:800 22px 'JetBrains Mono',monospace;color:#111;border:2px solid #f9a8d4;border-radius:8px;padding:4px 10px;background:linear-gradient(135deg,#fff,#e0f2fe);box-shadow:0 0 14px #f472b655}\n.lep{font:500 13px 'JetBrains Mono',monospace;color:var(--dim);white-space:nowrap}\n.llike{font:500 12px 'JetBrains Mono',monospace;color:var(--dim);background:none;border:none;cursor:pointer;white-space:nowrap;padding:4px}\n.llike.on{color:#ec4899}\n.llike:disabled{cursor:default}\n@media(max-width:560px){.lrow{grid-template-columns:34px 1fr auto;}.lep{grid-column:2}.llike{grid-column:3}}\n.modal{position:fixed;inset:0;background:#0007;display:none;align-items:center;justify-content:center;z-index:12;padding:16px}\n.modal.show{display:flex}\n.mbox{background:var(--card);color:var(--txt);border-radius:14px;padding:22px;width:100%;max-width:400px}\n.mbox label{display:block;font:600 13px Inter;margin-top:12px}\n.mbox input{display:block;width:100%;margin-top:6px;padding:10px 12px;border:1.5px solid var(--line);border-radius:8px;font:500 15px Inter}\n.colors{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}\n.colors button{width:28px;height:28px;border-radius:50%;border:3px solid var(--card);box-shadow:0 0 0 1px var(--line);cursor:pointer}\n.colors button.on{box-shadow:0 0 0 2px var(--txt)}\n.merr{color:#dc2626;font-size:13px;margin-top:10px;min-height:1em}\n.acct{margin-left:auto;display:flex;align-items:center;gap:8px}\n.acct .btn{padding:7px 12px;font-size:12px}\n.acct .who{font:800 13px Inter;text-transform:uppercase;cursor:pointer;background:none;border:none}\n.atabs{display:flex;gap:6px;margin-bottom:6px}\n.atabs button{flex:1;padding:9px;border:1.5px solid var(--line);background:var(--card);border-radius:8px;font:700 13px Inter;cursor:pointer;color:var(--dim)}\n.atabs button.on{border-color:var(--txt);color:var(--txt)}\n.guest{font-size:12px;color:var(--dim);margin-top:8px;text-align:center}\n.guest a{color:var(--acc);font-weight:700;cursor:pointer;text-decoration:underline}\n.numbox.mythic{animation:mythglow 1.6s ease-in-out infinite}\n@keyframes mythglow{50%{box-shadow:0 6px 50px #ef4444aa}}\n.adm{width:100%;background:var(--card);border:1px solid var(--line);border-radius:12px;overflow:hidden}\n.adm-top{display:flex;gap:8px;padding:12px;border-bottom:1px solid var(--line);align-items:center;flex-wrap:wrap}\n.adm-top input{flex:1;min-width:160px;padding:9px 12px;border:1.5px solid var(--line);border-radius:8px;font:500 14px Inter}\n.adm-row{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);flex-wrap:wrap}\n.adm-row .u{font:800 14px Inter;min-width:120px}\n.adm-row .st{font:500 12px 'JetBrains Mono',monospace;color:var(--dim);flex:1}\n.adm-row .btn{padding:6px 10px;font-size:11px}\n.adm-row .btn.red{color:#dc2626}\n.badge-admin{font:700 10px Inter;background:var(--txt);color:var(--card);border-radius:4px;padding:2px 5px;margin-left:6px;vertical-align:2px}\n.theme-btn{background:none;border:1.5px solid var(--line);border-radius:10px;padding:6px 9px;font-size:16px;cursor:pointer;line-height:1}\n.tpop{position:fixed;top:56px;right:16px;z-index:11;background:var(--card);color:var(--txt);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:0 10px 40px #0003;display:none;width:280px}\n.tpop.show{display:block}\n.tpop h5{font:800 12px Inter;text-transform:uppercase;letter-spacing:.5px;color:var(--dim);margin:0 0 10px}\n.tgrid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}\n.tgrid button{aspect-ratio:1;border-radius:50%;border:3px solid var(--card);box-shadow:0 0 0 1px var(--line);cursor:pointer}\n.tgrid button.on{box-shadow:0 0 0 2px var(--txt)}\n.tmode{display:flex;gap:6px;margin-top:14px}\n.tmode button{flex:1;padding:8px;border:1.5px solid var(--line);background:var(--card);color:var(--dim);border-radius:8px;font:700 12px Inter;cursor:pointer}\n.tmode button.on{border-color:var(--txt);color:var(--txt)}\n.tname{margin-top:10px;font:600 12px Inter;color:var(--sub);text-align:center}\n.ci .meta{gap:6px;align-items:center}\n.ci .cep{font:700 11px 'JetBrains Mono',monospace;color:var(--acctext);background:var(--accsoft);border:1px solid var(--accline);border-radius:999px;padding:1px 7px;margin-left:auto}\n.lrow[data-user]{cursor:pointer}\n.lrow[data-user]:hover{background:var(--soft)}\n.lrow.me[data-user]:hover{background:var(--hl)}\n.pbox{max-width:540px;max-height:90vh;overflow:auto}\n.phead{display:flex;align-items:baseline;gap:8px;flex-wrap:wrap}\n.phead .pn{font:800 24px Inter;text-transform:uppercase;word-break:break-all}\n.pmotto{font:500 13px 'JetBrains Mono',monospace;color:var(--sub);margin-top:4px}\n.psince{font-size:12px;color:var(--dim);margin-top:4px}\n.pgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:16px}\n.pstat{background:var(--soft);border-radius:10px;padding:10px;text-align:center}\n.pstat b{display:block;font:800 18px 'JetBrains Mono',monospace;color:var(--txt);word-break:break-all}\n.pstat span{font:600 10px Inter;text-transform:uppercase;letter-spacing:.4px;color:var(--dim)}\n.psec{margin-top:18px}\n.psec h5{font:800 12px Inter;text-transform:uppercase;letter-spacing:.5px;color:var(--dim);margin:0 0 8px}\n.pbest{display:flex;align-items:center;gap:14px;flex-wrap:wrap}\n.pbest .bn{font:800 34px 'JetBrains Mono',monospace;border:3px solid;border-radius:12px;padding:6px 16px}\n.pbest .bi{font-size:13px;color:var(--sub);line-height:1.6}\n.ptop{display:flex;flex-direction:column;gap:5px}\n.ptop div{display:flex;gap:10px;align-items:center;font:600 13px 'JetBrains Mono',monospace}\n.ptop .tn{min-width:72px;font-weight:800}\n.ptop .tt{font:700 10px Inter;text-transform:uppercase;border:1.5px solid currentColor;border-radius:4px;padding:1px 5px}\n.ptop .te{margin-left:auto;color:var(--dim)}\n.pbar{display:grid;grid-template-columns:86px 1fr 64px;gap:8px;align-items:center;font:600 12px Inter;margin-bottom:6px}\n.pbar .tr{height:8px;background:var(--soft);border-radius:99px;overflow:hidden}\n.pbar .tr i{display:block;height:100%;border-radius:99px}\n.pbar .v{text-align:right;font-family:'JetBrains Mono',monospace;color:var(--dim)}\n.pbadges{display:flex;flex-direction:column;gap:6px}\n.pbadge{display:flex;gap:8px;align-items:center;background:var(--soft);border-radius:8px;padding:7px 10px;font-size:13px}\n.pbadge b{text-transform:uppercase}\n.pbadge .r{margin-left:auto;font:700 11px Inter;text-transform:uppercase}\n.pnote{font-size:12px;color:var(--dim)}\n@media(max-width:480px){.pgrid{grid-template-columns:repeat(2,1fr)}}\n</style>\n</head>\n<body>\n<div class=\"calib\" id=\"calib\"><div style=\"font:800 22px 'JetBrains Mono'\">Infini<span style=\"color:#f59e0b\">Roll</span></div><div>Loading\u2026</div></div>\n\n<div class=\"top\">\n  <div class=\"brand\">Infini<span>Roll</span> \u221e</div>\n  <button class=\"lnk on\" data-tab=\"roll\">\ud83c\udfb2 Roll</button>\n  <button class=\"lnk\" data-tab=\"board\">\ud83c\udfc6 Leaderboard</button>\n  <button class=\"lnk\" data-tab=\"coll\">\ud83d\udcd6 Badges <span id=\"collCount\"></span></button>\n  <button class=\"lnk\" data-tab=\"rarity\">\u2139\ufe0f Rarity</button>\n  <button class=\"lnk\" data-tab=\"admin\" id=\"adminTab\" style=\"display:none\">\ud83d\udee1\ufe0f Admin</button>\n  <div class=\"acct\"><button class=\"theme-btn\" id=\"themeBtn\" title=\"Theme\">\ud83c\udfa8</button><span id=\"acct\" style=\"display:flex;align-items:center;gap:8px\"></span></div>\n</div>\n\n<div class=\"main\">\n  <!-- ROLL -->\n  <section id=\"tab-roll\" style=\"width:100%;display:flex;flex-direction:column;align-items:center\">\n    <div class=\"numbox\" id=\"numbox\"><div class=\"num\" id=\"num\">?</div></div>\n    <div class=\"tierline\" id=\"tierline\"><span class=\"tag\" style=\"color:#aaa\">Ready</span><span class=\"dot\"></span><span style=\"color:var(--dim)\">0 to 1 000 000</span></div>\n    <div class=\"ep\" id=\"ep\">0 EP</div>\n    <div class=\"life\"><span id=\"life\">0</span> EP<small>Your lifetime EP \u00b7 <span id=\"rolls\">0</span> rolls</small></div>\n    <div class=\"actions\">\n      <button class=\"btn roll\" id=\"rollBtn\" disabled>\ud83c\udfb2 Roll</button>\n      <button class=\"btn\" id=\"shareBtn\">\u2197 Share</button>\n    </div>\n    <div class=\"hint\">Space = roll \u00b7 no cooldown</div>\n    <div class=\"guest\" id=\"guestNote\"></div>\n\n    <h3>Badge breakdown</h3>\n    <div class=\"h3s\" id=\"bcount\">Make your first roll</div>\n    <div class=\"list\" id=\"blist\"></div>\n  </section>\n\n  <!-- BOARD -->\n  <section id=\"tab-board\" style=\"width:100%;display:none\">\n    <div class=\"lb\">\n      <div class=\"lbtabs\" id=\"lbtabs\"><button data-v=\"day\" class=\"on\">Today</button><button data-v=\"week\">This week</button><button data-v=\"all\">All-time</button><button data-v=\"badges\">Badges</button></div>\n      <div class=\"lbme\" id=\"lbme\"></div>\n      <div id=\"lbrows\"><div class=\"empty\">Loading leaderboard\u2026</div></div>\n    </div>\n  </section>\n\n  <!-- ADMIN -->\n  <section id=\"tab-admin\" style=\"width:100%;display:none\">\n    <h3 style=\"margin-top:0\">Admin panel</h3>\n    <div class=\"h3s\" id=\"admCount\"></div>\n    <div class=\"adm\" style=\"margin-top:14px\">\n      <div class=\"adm-top\"><input id=\"admSearch\" placeholder=\"Search a player\u2026\" autocomplete=\"off\"><button class=\"btn\" id=\"admRefresh\">Refresh</button></div>\n      <div id=\"admRows\"><div class=\"empty\">Loading\u2026</div></div>\n    </div>\n  </section>\n\n  <!-- RARITY -->\n  <section id=\"tab-rarity\" style=\"width:100%;display:none\">\n    <div class=\"rarity\">\n      <h2>Rarity</h2>\n      <div class=\"rgrid\">\n        <div>\n          <h4>Number rarity</h4>\n          <p>Your roll's overall rarity is based on your total EP compared to all possible rolls. It shows how your roll ranks:</p>\n          <div class=\"rt\" id=\"rtNum\"></div>\n        </div>\n        <div>\n          <h4>Badge rarity</h4>\n          <p>Each badge has a rarity based on how likely you are to roll it. Rarer badges are worth more EP. Badge rarity is determined by probability:</p>\n          <div class=\"rt\" id=\"rtBadge\"></div>\n        </div>\n      </div>\n      <p class=\"note\">Numbers range from 0 to 1 000 000. Every number has the same odds, except <b>0</b> (1 in 25 000 000) and <b>1 000 000</b> (1 in 100 000 000). A badge is worth about 100 \u00f7 its probability in EP.</p>\n    </div>\n  </section>\n\n  <!-- COLLECTION -->\n  <section id=\"tab-coll\" style=\"width:100%;display:none\">\n    <h3 style=\"margin-top:0\">Badge collection</h3>\n    <div class=\"h3s\" id=\"collSub\"></div>\n    <div class=\"coll\" id=\"coll\"></div>\n  </section>\n</div>\n<div class=\"cut\" id=\"cut\"><div class=\"cutTier\" id=\"cutTier\"></div><div class=\"cutNum\" id=\"cutNum\"></div><div class=\"cutSub\" id=\"cutSub\"></div><div class=\"cutHint\">click to continue</div></div>\n<div class=\"modal\" id=\"authModal\"><form class=\"mbox\" id=\"authForm\" autocomplete=\"on\">\n  <div class=\"atabs\"><button type=\"button\" data-m=\"login\" class=\"on\">Log in</button><button type=\"button\" data-m=\"signup\">Sign up</button></div>\n  <label>Username<input id=\"aUser\" name=\"username\" maxlength=\"16\" required autocomplete=\"username\" placeholder=\"3\u201316 letters, numbers or _\"></label>\n  <label>Password<input id=\"aPass\" name=\"password\" type=\"password\" minlength=\"6\" maxlength=\"100\" required autocomplete=\"current-password\" placeholder=\"At least 6 characters\"></label>\n  <label id=\"aPass2Wrap\" style=\"display:none\">Confirm password<input id=\"aPass2\" type=\"password\" maxlength=\"100\" autocomplete=\"new-password\"></label>\n  <div class=\"merr\" id=\"aErr\"></div>\n  <div style=\"display:flex;gap:8px;justify-content:flex-end;margin-top:12px\"><button type=\"button\" class=\"btn\" data-close>Cancel</button><button type=\"submit\" class=\"btn roll\" id=\"aSubmit\" style=\"padding:10px 18px;font-size:14px\">Log in</button></div>\n</form></div>\n<div class=\"modal\" id=\"acctModal\"><div class=\"mbox\">\n  <h3 style=\"margin:0 0 2px;text-align:left\" id=\"acName\"></h3>\n  <div class=\"h3s\" style=\"text-align:left\" id=\"acStats\"></div>\n  <form id=\"profForm\">\n    <label>Motto <span style=\"color:var(--dim)\">(optional)</span><input id=\"pMotto\" maxlength=\"48\" placeholder=\"e.g. trinity is all\" autocomplete=\"off\"></label>\n    <label>Emojis <span style=\"color:var(--dim)\">(up to 4)</span><input id=\"pEmoji\" maxlength=\"12\" placeholder=\"\ud83c\udf40\ud83d\udd25\" autocomplete=\"off\"></label>\n    <label>Name color</label><div class=\"colors\" id=\"pColors\"></div>\n    <div style=\"display:flex;justify-content:flex-end;margin-top:12px\"><button type=\"submit\" class=\"btn roll\" style=\"padding:9px 16px;font-size:13px\">Save profile</button></div>\n  </form>\n  <form id=\"pwForm\" style=\"border-top:1px solid var(--line);margin-top:16px;padding-top:4px\">\n    <label>Current password<input id=\"pwCur\" type=\"password\" autocomplete=\"current-password\" required></label>\n    <label>New password<input id=\"pwNew\" type=\"password\" minlength=\"6\" maxlength=\"100\" autocomplete=\"new-password\" required></label>\n    <div style=\"display:flex;justify-content:flex-end;margin-top:12px\"><button type=\"submit\" class=\"btn\" style=\"padding:9px 16px;font-size:13px\">Change password</button></div>\n  </form>\n  <div class=\"merr\" id=\"acErr\"></div>\n  <div style=\"display:flex;justify-content:space-between;margin-top:12px\"><button type=\"button\" class=\"btn\" id=\"logoutBtn\" style=\"color:#dc2626\">Log out</button><button type=\"button\" class=\"btn\" data-close>Close</button></div>\n</div></div>\n<div class=\"modal\" id=\"admModal\"><div class=\"mbox\">\n  <h3 style=\"margin:0 0 2px;text-align:left\">Edit <span id=\"admName\"></span></h3>\n  <div class=\"h3s\" style=\"text-align:left\" id=\"admInfo\"></div>\n  <form id=\"admRenameForm\"><label>New username<input id=\"admNewName\" maxlength=\"16\" autocomplete=\"off\"></label>\n    <div style=\"display:flex;justify-content:flex-end;margin-top:10px\"><button type=\"submit\" class=\"btn roll\" style=\"padding:8px 14px;font-size:13px\">Change username</button></div></form>\n  <form id=\"admPwForm\" style=\"border-top:1px solid var(--line);margin-top:14px;padding-top:2px\"><label>New password<input id=\"admNewPw\" type=\"text\" minlength=\"6\" maxlength=\"100\" autocomplete=\"off\" placeholder=\"At least 6 characters\"></label>\n    <div style=\"display:flex;justify-content:flex-end;margin-top:10px\"><button type=\"submit\" class=\"btn roll\" style=\"padding:8px 14px;font-size:13px\">Set password</button></div></form>\n  <div style=\"border-top:1px solid var(--line);margin-top:14px;padding-top:14px;display:flex;gap:8px;flex-wrap:wrap\">\n    <button type=\"button\" class=\"btn\" id=\"admReset\">Reset stats</button>\n    <button type=\"button\" class=\"btn\" id=\"admDelete\" style=\"color:#dc2626\">Delete account</button>\n  </div>\n  <div class=\"merr\" id=\"admErr\"></div>\n  <div style=\"display:flex;justify-content:flex-end;margin-top:8px\"><button type=\"button\" class=\"btn\" data-close>Close</button></div>\n</div></div>\n<div class=\"tpop\" id=\"tpop\">\n  <h5>Theme color</h5><div class=\"tgrid\" id=\"tgrid\"></div>\n  <div class=\"tmode\" id=\"tmode\"><button data-m=\"light\">\u2600\ufe0f Light</button><button data-m=\"dark\">\ud83c\udf19 Dark</button></div>\n  <div class=\"tname\" id=\"tname\"></div>\n</div>\n<div class=\"modal\" id=\"playerModal\"><div class=\"mbox pbox\" id=\"playerBox\"></div></div>\n<div class=\"toast\" id=\"toast\"></div>\n\n<script src=\"/game.js\"></script>\n<script>\nconst $=id=>document.getElementById(id);\nconst f=n=>String(Math.round(n)).replace(/\\B(?=(\\d{3})+(?!\\d))/g,\" \");\nconst fmtN=n=>String(n);\nconst esc=t=>String(t??\"\").replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst COLORS=[\"#111111\",\"#ef4444\",\"#f97316\",\"#eab308\",\"#22c55e\",\"#06b6d4\",\"#3b82f6\",\"#a855f7\",\"#ec4899\"];\nconst wait=ms=>new Promise(r=>setTimeout(r,ms));\n\nasync function api(path,body){\n  const opt=body===undefined?{credentials:\"same-origin\"}:{method:\"POST\",credentials:\"same-origin\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)};\n  let res;\n  try{res=await fetch(path,opt)}catch(e){throw new Error(\"Can't reach the server\")}\n  let data={};try{data=await res.json()}catch(e){}\n  if(!res.ok)throw new Error(data.error||(\"Error \"+res.status));\n  return data;\n}\n\n// ---------- THEMES ----------\nconst THEMES=[\n  {k:\"white\", n:\"White\", c:\"#ea580c\",sw:\"#ffffff\",neutral:true},\n  {k:\"black\", n:\"Black\", c:\"#a3a3a3\",sw:\"#111111\",neutral:true,forceDark:true},\n  {k:\"gray\",  n:\"Gray\",  c:\"#6b7280\",sw:\"#9ca3af\"},\n  {k:\"red\",   n:\"Red\",   c:\"#ef4444\",sw:\"#ef4444\"},\n  {k:\"orange\",n:\"Orange\",c:\"#f97316\",sw:\"#f97316\"},\n  {k:\"yellow\",n:\"Yellow\",c:\"#eab308\",sw:\"#facc15\"},\n  {k:\"green\", n:\"Green\", c:\"#22c55e\",sw:\"#22c55e\"},\n  {k:\"cyan\",  n:\"Cyan\",  c:\"#06b6d4\",sw:\"#06b6d4\"},\n  {k:\"blue\",  n:\"Blue\",  c:\"#3b82f6\",sw:\"#3b82f6\"},\n  {k:\"purple\",n:\"Purple\",c:\"#a855f7\",sw:\"#a855f7\"},\n  {k:\"pink\",  n:\"Pink\",  c:\"#ec4899\",sw:\"#ec4899\"},\n  {k:\"brown\", n:\"Brown\", c:\"#a16207\",sw:\"#92400e\"}\n];\nconst hex2rgb=h=>[1,3,5].map(i=>parseInt(h.slice(i,i+2),16));\nconst rgb2hex=a=>\"#\"+a.map(v=>Math.round(Math.max(0,Math.min(255,v))).toString(16).padStart(2,\"0\")).join(\"\");\nconst mix=(a,b,t)=>{const x=hex2rgb(a),y=hex2rgb(b);return rgb2hex(x.map((v,i)=>v+(y[i]-v)*t))};\nconst lum=h=>{const [r,g,b]=hex2rgb(h).map(v=>{v/=255;return v<=.03928?v/12.92:((v+.055)/1.055)**2.4});return .2126*r+.7152*g+.0722*b};\nlet THEME={k:\"white\",mode:\"light\"};\ntry{const t=JSON.parse(localStorage.getItem(\"ir_theme\"));if(t&&THEMES.some(x=>x.k===t.k))THEME={k:t.k,mode:t.mode===\"dark\"?\"dark\":\"light\"}}catch(e){}\nfunction applyTheme(save){\n  const th=THEMES.find(x=>x.k===THEME.k)||THEMES[0];\n  if(th.forceDark)THEME.mode=\"dark\";\n  const dark=THEME.mode===\"dark\",c=th.c,tint=th.neutral?0:1,v={};\n  if(!dark){\n    v.bg=th.neutral?\"#faf8f6\":mix(\"#ffffff\",c,.08);v.card=\"#ffffff\";v.line=mix(\"#ece7e2\",c,.18*tint);\n    v.txt=\"#1c1917\";v.dim=mix(\"#8a817a\",c,.2*tint);v.sub=\"#57534e\";v.soft=mix(\"#f5f5f4\",c,.08*tint);\n    v.acctext=mix(c,\"#000000\",.35);v.accsoft=mix(\"#ffffff\",c,.1);v.accline=mix(\"#ffffff\",c,.45);v.hl=mix(\"#ffffff\",c,.1);\n  }else{\n    v.bg=th.k===\"black\"?\"#000000\":mix(\"#0c0a09\",c,.1*tint);v.card=th.k===\"black\"?\"#111111\":mix(\"#1c1917\",c,.1*tint);\n    v.line=th.k===\"black\"?\"#262626\":mix(\"#2e2a28\",c,.25*tint);v.txt=\"#f5f5f4\";v.dim=\"#a8a29e\";v.sub=\"#d6d3d1\";\n    v.soft=mix(\"#292524\",c,.15*tint);v.acctext=mix(c,\"#ffffff\",.35);v.accsoft=mix(v.card,c,.16);v.accline=mix(v.card,c,.55);v.hl=mix(v.card,c,.18);\n  }\n  v.acc=c;v.acc2=mix(c,\"#000000\",.18);v.accfg=lum(c)>.45?\"#111111\":\"#ffffff\";\n  const root=document.documentElement.style;\n  for(const k in v)root.setProperty(\"--\"+k,v[k]);\n  root.setProperty(\"color-scheme\",dark?\"dark\":\"light\");\n  document.querySelector('meta[name=theme-color]')?.setAttribute(\"content\",v.bg);\n  if(save){try{localStorage.setItem(\"ir_theme\",JSON.stringify(THEME))}catch(e){}if(typeof ME!==\"undefined\"&&ME)api(\"/api/profile\",{theme:THEME}).catch(()=>{})}\n  renderThemePicker();\n  if(typeof current!==\"undefined\"&&current){const t=TIERS.find(t=>current.pct<=t[0]);paintNumber(t[1])}\n}\nfunction renderThemePicker(){\n  const g=document.getElementById(\"tgrid\");if(!g)return;\n  g.innerHTML=THEMES.map(t=>`<button data-t=\"${t.k}\" title=\"${t.n}\" style=\"background:${t.sw}\" class=\"${t.k===THEME.k?\"on\":\"\"}\"></button>`).join(\"\");\n  [...document.querySelectorAll(\"#tmode button\")].forEach(b=>{b.classList.toggle(\"on\",b.dataset.m===THEME.mode);b.disabled=!!THEMES.find(x=>x.k===THEME.k)?.forceDark&&b.dataset.m===\"light\"});\n  document.getElementById(\"tname\").textContent=(THEMES.find(x=>x.k===THEME.k)||THEMES[0]).n+\" \u00b7 \"+(THEME.mode===\"dark\"?\"Dark\":\"Light\");\n}\n\n// ---------- STATE ----------\n// Logged in: progress comes from the server. Guest: kept on this device only.\nconst GKEY=\"infiniroll_guest_v1\";\nlet ME=null;            // {username,motto,emoji,color}\nlet IS_ADMIN=false;\nlet S=emptyProgress();\nlet busy=false,current=null;\nfunction emptyProgress(){return{life:0,rolls:0,top:[],seen:{},last:null}}\nfunction loadGuest(){try{const d=JSON.parse(localStorage.getItem(GKEY));if(d)return Object.assign(emptyProgress(),d)}catch(e){}return emptyProgress()}\nfunction saveGuest(){if(ME)return;try{localStorage.setItem(GKEY,JSON.stringify(S))}catch(e){}}\n\n// ---------- UI ----------\nfunction colorize(el,col){el.classList.toggle(\"rainbow\",col===\"rainbow\");el.style.color=col===\"rainbow\"?\"\":col}\nfunction pctText(p){if(p>0.5){const b=(1-p)*100;return \"BOTTOM \"+(b<1?\"1\":String(Math.ceil(b)))+\"%\"}if(p<0.0001)return \"1 IN \"+f(Math.round(1/p));const v=p*100;return \"TOP \"+(v>=1?String(Math.ceil(v)):v>=0.1?v.toFixed(1):v.toFixed(2))+\"%\"}\n\nfunction showResult(r,animate){\n  $(\"num\").textContent=fmtN(r.n);\n  const tier=TIERS.find(t=>r.pct<=t[0]);\n  $(\"tierline\").innerHTML=`<span class=\"tag\" id=\"tierTag\">${tier[1]}</span><span class=\"dot\"></span><span id=\"pctTxt\" style=\"font-weight:700\">${pctText(r.pct)}</span>`;\n  colorize($(\"tierTag\"),tier[2]);$(\"pctTxt\").style.color=\"#d97706\";\n  $(\"ep\").textContent=f(r.total)+\" EP\";\n  const nb=$(\"numbox\");nb.classList.remove(\"spin\");\n  if(animate){nb.classList.remove(\"pop\");void nb.offsetWidth;nb.classList.add(\"pop\")}\n  paintNumber(tier[1]);\n  const s=String(r.n);\n  const list=r.badges.map(id=>BADGES.find(b=>b.id===id)).filter(Boolean).sort((a,b)=>b.ep-a.ep);\n  $(\"bcount\").textContent=`${list.length} badge${list.length>1?\"s\":\"\"} earned`;\n  $(\"blist\").innerHTML=list.length?list.map((b,i)=>{\n    let m=b.test(s,r.n);if(m===true)m=Array(s.length).fill(1);if(!m)m=[];\n    return `<div class=\"bcard\" style=\"animation-delay:${Math.min(i*40,400)}ms\">\n      <div class=\"bhead\"><span>${b.icon}</span><span class=\"bname\">${b.name}</span><span class=\"rar\" style=\"color:${b.col}\">${b.rar}</span><span class=\"bep\">+${f(b.ep)} EP</span></div>\n      <div class=\"bdesc\">${b.desc} <span style=\"opacity:.7\">\u00b7 1 in ${f(1/b.p)}</span></div>\n      <div class=\"digits\">${s.split(\"\").map((c,j)=>`<div class=\"d ${m[j]===1?'a':m[j]===2?'b':''}\">${c}</div>`).join(\"\")}</div></div>`}).join(\"\")\n    :`<div class=\"empty\">No badges\u2026 roll again!</div>`;\n}\n// Number box colors per roll rarity\nconst TIER_STYLE={\n  Trash:   {text:\"#a16207\",border:\"#facc15\",bg1:\"#fefce8\",bg2:\"#fef08a\",glow:\"#eab30833\"},\n  Common:  {text:\"#44403c\",border:\"#d6d3d1\",bg1:\"#ffffff\",bg2:\"#f5f5f4\",glow:\"#0000000d\"},\n  Uncommon:{text:\"#047857\",border:\"#6ee7b7\",bg1:\"#ecfdf5\",bg2:\"#d1fae5\",glow:\"#10b98133\"},\n  Rare:    {text:\"#1d4ed8\",border:\"#93c5fd\",bg1:\"#eff6ff\",bg2:\"#dbeafe\",glow:\"#3b82f644\"},\n  Epic:    {text:\"#7e22ce\",border:\"#d8b4fe\",bg1:\"#faf5ff\",bg2:\"#f3e8ff\",glow:\"#a855f755\"},\n  Anomaly: {text:\"#c2410c\",border:\"#fdba74\",bg1:\"#fff7ed\",bg2:\"#ffedd5\",glow:\"#f9731666\"},\n  Mythic:  {text:\"#b91c1c\",border:\"#f87171\",bg1:\"#fef2f2\",bg2:\"#fecaca\",glow:\"#ef444488\"}\n};\nfunction paintNumber(name){\n  const st=TIER_STYLE[name],nb=$(\"numbox\"),num=$(\"num\"),ep=$(\"ep\"),pt=$(\"pctTxt\");\n  nb.classList.toggle(\"mythic\",name===\"Mythic\");\n  if(!st){num.style.color=\"\";nb.style.borderColor=\"\";nb.style.background=\"\";nb.style.boxShadow=\"\";ep.style.color=\"\";ep.style.borderColor=\"\";ep.style.background=\"\";return}\n  const dark=THEME.mode===\"dark\";\n  num.style.color=dark?st.border:st.text;nb.style.borderColor=st.border;\n  nb.style.background=dark?`linear-gradient(${st.border}1f,${st.border}38)`:`linear-gradient(${st.bg1},${st.bg2})`;nb.style.boxShadow=`0 6px 30px ${st.glow}`;\n  ep.style.color=dark?st.border:st.text;ep.style.borderColor=st.border;ep.style.background=dark?st.border+\"22\":st.bg1;\n  if(pt)pt.style.color=dark?st.border:st.text;\n}\nfunction clearResult(){\n  $(\"num\").textContent=\"?\";$(\"ep\").textContent=\"0 EP\";$(\"blist\").innerHTML=\"\";$(\"bcount\").textContent=\"Make your first roll\";\n  $(\"tierline\").innerHTML='<span class=\"tag\" style=\"color:#aaa\">Ready</span><span class=\"dot\"></span><span style=\"color:var(--dim)\">0 to 1 000 000</span>';\n  paintNumber(null);\n}\nfunction renderStats(){\n  $(\"life\").textContent=f(S.life);$(\"rolls\").textContent=f(S.rolls);\n  $(\"collCount\").textContent=`${Object.keys(S.seen).length}/${BADGES.length}`;\n}\nfunction renderColl(){\n  const n=Object.keys(S.seen).length;\n  $(\"collSub\").textContent=`${n} / ${BADGES.length} badges discovered`;\n  $(\"coll\").innerHTML=[...BADGES].sort((a,b)=>a.ep-b.ep).map(b=>{const c=S.seen[b.id];\n    return `<div class=\"ci ${c?'':'lock'}\"><b>${c?b.icon+\" \"+b.name:\"\ud83d\udd12 ???\"}</b>${c?b.desc:\"Not earned yet.\"}\n    <div class=\"meta\"><span style=\"color:${b.col};font-weight:700\">${b.rar}</span><span class=\"cep\">+${f(b.ep)} EP</span><span>${c?\"\u00d7\"+f(c):\"1/\"+f(1/b.p)}</span></div></div>`}).join(\"\");\n}\nfunction renderAccount(){\n  $(\"acct\").innerHTML=ME\n    ?`<button class=\"who\" id=\"whoBtn\" style=\"color:${esc(ME.color)}\">${esc(ME.username)}</button>`\n    :`<button class=\"btn\" id=\"loginBtn\">Log in</button><button class=\"btn roll\" id=\"signupBtn\" style=\"padding:7px 12px;font-size:12px\">Sign up</button>`;\n  if(ME)$(\"whoBtn\").onclick=openAccount;else{$(\"loginBtn\").onclick=()=>openAuth(\"login\");$(\"signupBtn\").onclick=()=>openAuth(\"signup\")}\n  $(\"guestNote\").innerHTML=ME?\"\":`Playing as a guest \u2014 <a id=\"gSign\">sign up</a> to save your rolls and join the leaderboard.`;\n  const g=$(\"gSign\");if(g)g.onclick=()=>openAuth(\"signup\");\n}\nfunction renderAll(){renderStats();renderColl();renderAccount();LB.load()}\nfunction applyAccount(data){\n  ME=data.user||null;IS_ADMIN=!!(ME&&data.admin);\n  if(ME&&data.theme&&THEMES.some(x=>x.k===data.theme.k)){THEME={k:data.theme.k,mode:data.theme.mode===\"dark\"?\"dark\":\"light\"};applyTheme(false);try{localStorage.setItem(\"ir_theme\",JSON.stringify(THEME))}catch(e){}}\n  $(\"adminTab\").style.display=IS_ADMIN?\"\":\"none\";\n  if(!IS_ADMIN&&$(\"tab-admin\").style.display!==\"none\")document.querySelector('.lnk[data-tab=roll]').click();\n  S=ME?Object.assign(emptyProgress(),data.progress||{}):loadGuest();\n  current=S.last||null;\n  if(current)showResult(current,false);else clearResult();\n  renderAll();\n}\n\n// ---------- ROLL (the server picks the number) ----------\nasync function roll(){\n  if(busy)return;busy=true;$(\"rollBtn\").disabled=true;\n  const nb=$(\"numbox\");paintNumber(null);nb.classList.add(\"spin\");\n  const req=api(\"/api/roll\",{});\n  let stop=false;\n  (async()=>{for(let i=0;!stop;i++){$(\"num\").textContent=fmtN(Math.floor(Math.random()*1000000));await wait(35+Math.min(i,14)*3)}})();\n  let data;\n  try{[data]=await Promise.all([req,wait(550)])}catch(e){stop=true;nb.classList.remove(\"spin\");if(current)showResult(current,false);else clearResult();toast(e.message);busy=false;$(\"rollBtn\").disabled=false;return}\n  stop=true;await wait(10);\n  const r=data.result;current=r;\n  let fresh=[],record=false;\n  if(data.saved){fresh=data.fresh||[];record=data.record;S=Object.assign(emptyProgress(),data.progress)}\n  else{\n    const prevBest=S.top[0]?.total||0;\n    r.badges.forEach(id=>{if(!S.seen[id])fresh.push(id);S.seen[id]=(S.seen[id]||0)+1});\n    S.rolls++;S.life+=r.total;S.last=r;\n    S.top.push(r);S.top.sort((a,b)=>b.total-a.total);S.top=S.top.slice(0,25);\n    record=r.total>prevBest&&S.rolls>1;saveGuest();\n  }\n  showResult(r,true);renderStats();renderColl();\n  if(record)toast(\"\ud83c\udfc6 New record: \"+f(r.total)+\" EP\");\n  else if(fresh.length)toast(\"\u2728 New badge: \"+fresh.map(id=>BADGES.find(b=>b.id===id)?.name).join(\", \"));\n  if($(\"tab-board\").style.display!==\"none\")LB.load();\n  if(r.pct<=0.001)await cutscene(r);\n  busy=false;$(\"rollBtn\").disabled=false;\n}\nfunction cutscene(r){return new Promise(res=>{\n  const t=TIERS.find(t=>r.pct<=t[0]),c=$(\"cut\");\n  $(\"cutTier\").textContent=t[1];colorize($(\"cutTier\"),t[2]);\n  $(\"cutNum\").textContent=fmtN(r.n);colorize($(\"cutNum\"),\"#fff\");\n  $(\"cutSub\").textContent=pctText(r.pct)+\" \u00b7 \"+f(r.total)+\" EP\";\n  c.style.background=`radial-gradient(circle,${t[2]}55,#0c0a09f5 65%)`;c.classList.add(\"show\");\n  const close=()=>{c.classList.remove(\"show\");c.onclick=null;res()};c.onclick=close;\n})}\nfunction toast(t){const el=$(\"toast\");el.textContent=t;el.classList.add(\"show\");clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove(\"show\"),2200)}\n\n// ---------- LEADERBOARD ----------\nconst LB={view:\"day\",seq:0,\n  async load(){\n    const box=$(\"lbrows\"),meBox=$(\"lbme\"),seq=++this.seq;\n    meBox.innerHTML=ME?`Playing as <b style=\"color:${esc(ME.color)};cursor:pointer\" id=\"lbMe\">${esc(ME.username)}</b> <button class=\"btn\" id=\"lbEdit\">Edit profile</button>`\n      :`Log in to post your rolls and like other players. <button class=\"btn roll\" id=\"lbJoin\" style=\"padding:7px 14px;font-size:12px\">Sign up</button>`;\n    const b1=$(\"lbEdit\"),b2=$(\"lbJoin\"),b3=$(\"lbMe\");if(b1)b1.onclick=openAccount;if(b3)b3.onclick=()=>openPlayer(ME.username);if(b2)b2.onclick=()=>openAuth(\"signup\");\n    let data;\n    try{data=await api(\"/api/leaderboard?view=\"+this.view)}catch(e){if(seq===this.seq)box.innerHTML=`<div class=\"empty\">${esc(e.message)}</div>`;return}\n    if(seq!==this.seq)return;\n    const rows=data.rows;\n    if(!rows.length){box.innerHTML=`<div class=\"empty\">${this.view===\"day\"?\"Nobody has rolled today yet. Be the first!\":\"No entries yet.\"}</div>`;return}\n    const medals=[\"\ud83e\udd47\",\"\ud83e\udd48\",\"\ud83e\udd49\"];\n    box.innerHTML=rows.map((p,i)=>{\n      const col=COLORS.includes(p.color)?p.color:\"#111111\";\n      const right=this.view===\"badges\"?`<span class=\"lnum\">${p.badges}</span><span class=\"lep\">/ ${data.total} badges</span>`:`<span class=\"lnum\">${fmtN(p.n)}</span><span class=\"lep\">${f(p.total)} EP</span>`;\n      return `<div class=\"lrow ${p.me?\"me\":\"\"}\" data-user=\"${esc(p.username)}\" title=\"View profile\"><span class=\"lrank ${i<3?\"medal\":\"\"}\">${i<3?medals[i]:\"#\"+(i+1)}</span>\n        <span class=\"lname\" style=\"color:${col}\">${esc(p.username)}${p.emoji?`<span class=\"em\">${esc(p.emoji)}</span>`:\"\"}</span>\n        ${right}<button class=\"llike ${p.liked?\"on\":\"\"}\" data-like=\"${esc(p.username)}\" ${p.me?\"disabled\":\"\"}>${p.likes} ${p.liked?\"\u2665\":\"\u2661\"}</button>\n        ${p.motto?`<div class=\"lmotto\">${esc(p.motto)}</div>`:\"\"}</div>`}).join(\"\");\n  }\n};\n$(\"lbrows\").addEventListener(\"click\",async e=>{\n  const b=e.target.closest(\"[data-like]\");\n  if(!b){const r=e.target.closest(\".lrow[data-user]\");if(r)openPlayer(r.dataset.user);return}\n  if(!ME){openAuth(\"login\");return}\n  try{await api(\"/api/like/\"+encodeURIComponent(b.dataset.like),{});LB.load()}catch(err){toast(err.message)}\n});\n$(\"lbtabs\").addEventListener(\"click\",e=>{const b=e.target.closest(\"button\");if(!b)return;LB.view=b.dataset.v;[...$(\"lbtabs\").children].forEach(x=>x.classList.toggle(\"on\",x===b));LB.load()});\n\n// ---------- PLAYER PROFILE ----------\nconst TIER_ORDER=[\"Mythic\",\"Anomaly\",\"Epic\",\"Rare\",\"Uncommon\",\"Common\",\"Trash\"];\nconst RAR_ORDER=[\"Mythic\",\"Anomaly\",\"Epic\",\"Rare\",\"Uncommon\",\"Common\"];\nconst tierColor=n=>(TIERS.find(t=>t[1]===n)||[0,0,\"#888\"])[2];\nconst rarColor=n=>(RAR.find(r=>r[1]===n)||[0,0,\"#888\"])[2];\nconst tierOf=pct=>TIERS.find(t=>pct<=t[0])[1];\nasync function openPlayer(name){\n  const box=$(\"playerBox\");\n  box.innerHTML=`<div class=\"empty\">Loading\u2026</div>`;$(\"playerModal\").classList.add(\"show\");\n  let p;try{p=await api(\"/api/player/\"+encodeURIComponent(name))}catch(e){box.innerHTML=`<div class=\"empty\">${esc(e.message)}</div><div style=\"text-align:right\"><button class=\"btn\" data-close>Close</button></div>`;bindClose(box);return}\n  const col=COLORS.includes(p.color)?p.color:\"var(--txt)\";\n  const avg=p.rolls?p.life/p.rolls:0;\n  const best=p.top[0];\n  const bestT=best?tierOf(best.pct):null;\n  const st=bestT?TIER_STYLE[bestT]:null;\n  const dark=THEME.mode===\"dark\";\n  const days=p.created?Math.max(1,Math.ceil((Date.now()-p.created)/864e5)):null;\n  const totalTiers=Object.values(p.tiers).reduce((a,b)=>a+b,0);\n  const bar=(label,color,v,max,txt)=>`<div class=\"pbar\"><span style=\"color:${color}\">${label}</span><div class=\"tr\"><i style=\"width:${max?Math.max(v?2:0,v/max*100):0}%;background:${color}\"></i></div><span class=\"v\">${txt}</span></div>`;\n  const bdg=id=>{const b=BADGES.find(x=>x.id===id);return b?`<div class=\"pbadge\"><span>${b.icon}</span><b>${esc(b.name)}</b><span style=\"color:var(--dim)\">1 in ${f(1/b.p)}</span><span class=\"r\" style=\"color:${b.col}\">${b.rar}</span></div>`:\"\"};\n  box.innerHTML=`\n    <div class=\"phead\"><span class=\"pn\" style=\"color:${col}\">${esc(p.username)}</span>${p.emoji?`<span style=\"font-size:20px\">${esc(p.emoji)}</span>`:\"\"}</div>\n    ${p.motto?`<div class=\"pmotto\">${esc(p.motto)}</div>`:\"\"}\n    <div class=\"psince\">${p.created?`Playing since ${new Date(p.created).toLocaleDateString(\"en-GB\",{day:\"numeric\",month:\"long\",year:\"numeric\"})}`:\"\"}</div>\n    <div class=\"pgrid\">\n      <div class=\"pstat\"><b>${p.rank?\"#\"+p.rank:\"\u2014\"}</b><span>All-time rank / ${p.players}</span></div>\n      <div class=\"pstat\"><b>${f(p.rolls)}</b><span>Rolls${days?` \u00b7 ${f(p.rolls/days)}/day`:\"\"}</span></div>\n      <div class=\"pstat\"><b>${f(p.likes)} \u2665</b><span>Likes</span></div>\n      <div class=\"pstat\"><b>${f(p.life)}</b><span>Lifetime EP</span></div>\n      <div class=\"pstat\"><b>${f(avg)}</b><span>Avg EP / roll</span></div>\n      <div class=\"pstat\"><b>${p.badges}/${p.badgesTotal}</b><span>Badges (${Math.round(p.badges/p.badgesTotal*100)}%)</span></div>\n    </div>\n    ${best?`<div class=\"psec\"><h5>Best roll ever</h5><div class=\"pbest\">\n      <span class=\"bn\" style=\"color:${dark?st.border:st.text};border-color:${st.border};background:${dark?st.border+\"22\":`linear-gradient(${st.bg1},${st.bg2})`}\">${fmtN(best.n)}</span>\n      <span class=\"bi\"><b style=\"color:${tierColor(bestT)}\">${bestT.toUpperCase()}</b> \u00b7 ${pctText(best.pct)}<br>${f(best.total)} EP</span></div></div>`:\"\"}\n    ${p.today||p.week?`<div class=\"psec\"><h5>Recent bests</h5><div class=\"ptop\">\n      ${p.today?`<div><span style=\"color:var(--dim);min-width:72px\">Today</span><span class=\"tn\">${fmtN(p.today.n)}</span><span class=\"te\">${f(p.today.total)} EP</span></div>`:\"\"}\n      ${p.week?`<div><span style=\"color:var(--dim);min-width:72px\">This week</span><span class=\"tn\">${fmtN(p.week.n)}</span><span class=\"te\">${f(p.week.total)} EP</span></div>`:\"\"}\n    </div></div>`:\"\"}\n    ${p.top.length>1?`<div class=\"psec\"><h5>Top ${p.top.length} rolls</h5><div class=\"ptop\">${p.top.map((r,i)=>{const t=tierOf(r.pct);return `<div><span style=\"color:var(--dim)\">#${i+1}</span><span class=\"tn\">${fmtN(r.n)}</span><span class=\"tt\" style=\"color:${tierColor(t)}\">${t}</span><span class=\"te\">${f(r.total)} EP</span></div>`}).join(\"\")}</div></div>`:\"\"}\n    ${p.rarest.length?`<div class=\"psec\"><h5>Rarest badges found</h5><div class=\"pbadges\">${p.rarest.map(bdg).join(\"\")}</div></div>`:\"\"}\n    ${p.favorite?`<div class=\"psec\"><h5>Most earned rare badge</h5><div class=\"pbadges\">${bdg(p.favorite.id).replace('<span class=\"r\"',`<span style=\"color:var(--dim)\">\u00d7${f(p.favorite.count)}</span><span class=\"r\"`)}</div></div>`:\"\"}\n    <div class=\"psec\"><h5>Badge collection by rarity</h5>${RAR_ORDER.map(r=>{const x=p.byRarity[r]||{found:0,total:0};return bar(r,rarColor(r),x.found,x.total,`${x.found}/${x.total}`)}).join(\"\")}</div>\n    <div class=\"psec\"><h5>Roll luck</h5>${totalTiers?TIER_ORDER.map(t=>bar(t,tierColor(t),p.tiers[t]||0,totalTiers,`${Math.round((p.tiers[t]||0)/totalTiers*1000)/10}%`)).join(\"\")\n      +`<div class=\"pnote\">Expected: Mythic 1% \u00b7 Anomaly 4% \u00b7 Epic 5% \u00b7 Rare 15% \u00b7 Uncommon 25% \u00b7 Common 49% \u00b7 Trash 1%</div>`:`<div class=\"pnote\">No data yet: stats are counted from the next roll.</div>`}</div>\n    <div style=\"display:flex;justify-content:flex-end;margin-top:18px\"><button class=\"btn\" data-close>Close</button></div>`;\n  bindClose(box);\n}\nfunction bindClose(root){root.querySelectorAll(\"[data-close]\").forEach(b=>b.onclick=()=>b.closest(\".modal\").classList.remove(\"show\"))}\n\n// ---------- AUTH ----------\nlet authMode=\"login\";\nfunction openAuth(mode){\n  authMode=mode;\n  [...document.querySelectorAll(\".atabs button\")].forEach(b=>b.classList.toggle(\"on\",b.dataset.m===mode));\n  $(\"aPass2Wrap\").style.display=mode===\"signup\"?\"block\":\"none\";\n  $(\"aPass\").autocomplete=mode===\"signup\"?\"new-password\":\"current-password\";\n  $(\"aSubmit\").textContent=mode===\"signup\"?\"Create account\":\"Log in\";\n  $(\"aErr\").textContent=\"\";$(\"aPass\").value=\"\";$(\"aPass2\").value=\"\";\n  $(\"authModal\").classList.add(\"show\");setTimeout(()=>$(\"aUser\").focus(),50);\n}\ndocument.querySelectorAll(\".atabs button\").forEach(b=>b.onclick=()=>openAuth(b.dataset.m));\n$(\"authForm\").addEventListener(\"submit\",async e=>{\n  e.preventDefault();\n  const username=$(\"aUser\").value.trim(),password=$(\"aPass\").value;\n  if(authMode===\"signup\"&&password!==$(\"aPass2\").value){$(\"aErr\").textContent=\"Passwords don't match\";return}\n  $(\"aSubmit\").disabled=true;\n  try{\n    const data=await api(authMode===\"signup\"?\"/api/register\":\"/api/login\",{username,password});\n    $(\"authModal\").classList.remove(\"show\");applyAccount(data);\n    toast(authMode===\"signup\"?\"Welcome, \"+data.user.username+\"!\":\"Welcome back, \"+data.user.username+\"!\");\n  }catch(err){$(\"aErr\").textContent=err.message}\n  $(\"aSubmit\").disabled=false;\n});\nlet pColor=COLORS[0];\nfunction openAccount(){\n  if(!ME)return;\n  $(\"acName\").textContent=ME.username;$(\"acName\").style.color=ME.color;\n  $(\"acStats\").textContent=`${f(S.rolls)} rolls \u00b7 ${f(S.life)} EP \u00b7 ${Object.keys(S.seen).length} badges`;\n  $(\"pMotto\").value=ME.motto||\"\";$(\"pEmoji\").value=ME.emoji||\"\";pColor=COLORS.includes(ME.color)?ME.color:COLORS[0];\n  $(\"pColors\").innerHTML=COLORS.map(c=>`<button type=\"button\" data-c=\"${c}\" style=\"background:${c}\" class=\"${c===pColor?\"on\":\"\"}\"></button>`).join(\"\");\n  $(\"acErr\").textContent=\"\";$(\"pwCur\").value=\"\";$(\"pwNew\").value=\"\";\n  $(\"acctModal\").classList.add(\"show\");\n}\n$(\"pColors\").addEventListener(\"click\",e=>{const b=e.target.closest(\"[data-c]\");if(!b)return;pColor=b.dataset.c;[...$(\"pColors\").children].forEach(x=>x.classList.toggle(\"on\",x===b))});\n$(\"profForm\").addEventListener(\"submit\",async e=>{e.preventDefault();\n  try{const d=await api(\"/api/profile\",{motto:$(\"pMotto\").value,emoji:$(\"pEmoji\").value,color:pColor});ME=d.user;renderAccount();LB.load();$(\"acctModal\").classList.remove(\"show\");toast(\"Profile saved\")}\n  catch(err){$(\"acErr\").textContent=err.message}});\n$(\"pwForm\").addEventListener(\"submit\",async e=>{e.preventDefault();\n  try{await api(\"/api/password\",{current:$(\"pwCur\").value,next:$(\"pwNew\").value});$(\"pwCur\").value=\"\";$(\"pwNew\").value=\"\";toast(\"Password changed\")}\n  catch(err){$(\"acErr\").textContent=err.message}});\n$(\"logoutBtn\").onclick=async()=>{try{await api(\"/api/logout\",{})}catch(e){}$(\"acctModal\").classList.remove(\"show\");applyAccount({user:null});toast(\"Logged out\")};\ndocument.querySelectorAll(\"[data-close]\").forEach(b=>b.onclick=()=>b.closest(\".modal\").classList.remove(\"show\"));\ndocument.querySelectorAll(\".modal\").forEach(m=>m.addEventListener(\"mousedown\",e=>{if(e.target===m)m.classList.remove(\"show\")}));\n\n// ---------- NAV / KEYS ----------\n$(\"rollBtn\").onclick=roll;\n$(\"shareBtn\").onclick=async()=>{\n  if(!current){toast(\"Roll first!\");return}\n  const t=TIERS.find(t=>current.pct<=t[0]);\n  const top=current.badges.map(id=>BADGES.find(b=>b.id===id)).filter(Boolean).sort((a,b)=>b.ep-a.ep).slice(0,5).map(b=>b.icon).join(\"\");\n  const txt=`InfiniRoll \ud83c\udfb2 ${current.n}\\n${t[1].toUpperCase()} \u00b7 ${pctText(current.pct)} \u00b7 ${f(current.total)} EP\\n${top}\\n${location.origin}`;\n  try{await navigator.clipboard.writeText(txt);toast(\"Copied to clipboard\")}catch(e){toast(\"Can't copy here\")}\n};\ndocument.querySelectorAll(\".lnk\").forEach(b=>b.onclick=()=>{\n  document.querySelectorAll(\".lnk\").forEach(x=>x.classList.toggle(\"on\",x===b));\n  [\"roll\",\"board\",\"coll\",\"rarity\",\"admin\"].forEach(t=>$(\"tab-\"+t).style.display=t===b.dataset.tab?(t===\"roll\"?\"flex\":\"block\"):\"none\");\n  if(b.dataset.tab===\"board\")LB.load();\n  if(b.dataset.tab===\"admin\")ADM.load();\n});\ndocument.addEventListener(\"keydown\",e=>{\n  if(e.target.closest&&e.target.closest(\"input,textarea,button,.modal\"))return;\n  if(document.querySelector(\".modal.show\"))return;\n  if(e.code===\"Space\"){e.preventDefault();roll()}\n});\n\n// ---------- ADMIN PANEL ----------\nconst ADM={rows:[],sel:null,seq:0,t:null,\n  async load(){\n    const seq=++this.seq,box=$(\"admRows\");\n    let d;try{d=await api(\"/api/admin/users?q=\"+encodeURIComponent($(\"admSearch\").value.trim()))}catch(e){box.innerHTML=`<div class=\"empty\">${esc(e.message)}</div>`;return}\n    if(seq!==this.seq)return;\n    this.rows=d.rows;$(\"admCount\").textContent=`${d.count} account${d.count>1?\"s\":\"\"}`;\n    box.innerHTML=d.rows.length?d.rows.map((u,i)=>`<div class=\"adm-row\"><span class=\"u\">${esc(u.username)}${u.admin?'<span class=\"badge-admin\">ADMIN</span>':\"\"}</span>\n      <span class=\"st\">${f(u.rolls)} rolls \u00b7 ${f(u.life)} EP \u00b7 best ${u.best==null?\"\u2014\":fmtN(u.best)} \u00b7 ${u.badges} badges \u00b7 since ${new Date(u.created).toLocaleDateString()}</span>\n      <button class=\"btn\" data-edit=\"${i}\">Edit</button></div>`).join(\"\"):`<div class=\"empty\">No player found.</div>`;\n  },\n  open(u){\n    this.sel=u;$(\"admName\").textContent=u.username;\n    $(\"admInfo\").textContent=`${f(u.rolls)} rolls \u00b7 ${f(u.life)} EP \u00b7 ${u.sessions} active session${u.sessions===1?\"\":\"s\"}`;\n    $(\"admNewName\").value=u.username;$(\"admNewPw\").value=\"\";$(\"admErr\").textContent=\"\";\n    $(\"admDelete\").textContent=\"Delete account\";$(\"admDelete\").dataset.c=\"\";$(\"admReset\").textContent=\"Reset stats\";$(\"admReset\").dataset.c=\"\";\n    $(\"admModal\").classList.add(\"show\");\n  },\n  async act(path,body,msg){\n    try{await api(path,body);toast(msg);$(\"admModal\").classList.remove(\"show\");await this.load();\n      const m=await api(\"/api/me\");if(!m.user||m.user.username!==ME?.username)applyAccount(m);LB.load();}\n    catch(e){$(\"admErr\").textContent=e.message}\n  }\n};\n$(\"admRows\").addEventListener(\"click\",e=>{const b=e.target.closest(\"[data-edit]\");if(b)ADM.open(ADM.rows[+b.dataset.edit])});\n$(\"admSearch\").addEventListener(\"input\",()=>{clearTimeout(ADM.t);ADM.t=setTimeout(()=>ADM.load(),250)});\n$(\"admRefresh\").onclick=()=>ADM.load();\n$(\"admRenameForm\").addEventListener(\"submit\",e=>{e.preventDefault();const n=$(\"admNewName\").value.trim();\n  ADM.act(\"/api/admin/rename\",{username:ADM.sel.username,newName:n},`Renamed to ${n}`)});\n$(\"admPwForm\").addEventListener(\"submit\",e=>{e.preventDefault();\n  ADM.act(\"/api/admin/password\",{username:ADM.sel.username,password:$(\"admNewPw\").value},`Password changed for ${ADM.sel.username}`)});\nfunction confirmBtn(btn,label,fn){if(btn.dataset.c){fn()}else{btn.dataset.c=\"1\";btn.textContent=\"Click again to confirm\";setTimeout(()=>{btn.dataset.c=\"\";btn.textContent=label},3000)}}\n$(\"admDelete\").onclick=()=>confirmBtn($(\"admDelete\"),\"Delete account\",()=>ADM.act(\"/api/admin/delete\",{username:ADM.sel.username},`${ADM.sel.username} deleted`));\n$(\"admReset\").onclick=()=>confirmBtn($(\"admReset\"),\"Reset stats\",()=>ADM.act(\"/api/admin/reset\",{username:ADM.sel.username},`Stats reset for ${ADM.sel.username}`));\n\n// theme picker events\n$(\"themeBtn\").onclick=e=>{e.stopPropagation();$(\"tpop\").classList.toggle(\"show\")};\ndocument.addEventListener(\"click\",e=>{if(!e.target.closest(\"#tpop\")&&e.target!==$(\"themeBtn\"))$(\"tpop\").classList.remove(\"show\")});\n$(\"tgrid\").addEventListener(\"click\",e=>{const b=e.target.closest(\"[data-t]\");if(!b)return;THEME.k=b.dataset.t;const t=THEMES.find(x=>x.k===THEME.k);if(t.forceDark)THEME.mode=\"dark\";applyTheme(true)});\n$(\"tmode\").addEventListener(\"click\",e=>{const b=e.target.closest(\"[data-m]\");if(!b||b.disabled)return;THEME.mode=b.dataset.m;applyTheme(true)});\napplyTheme(false);\n\nconst RT_NUM=[[\"Trash\",\"#eab308\",\"Bottom 1%\"],[\"Common\",\"#e7e5e4\",\"Bottom 50%\"],[\"Uncommon\",\"#10b981\",\"Top 50-25%\"],[\"Rare\",\"#60a5fa\",\"Top 25-10%\"],[\"Epic\",\"#c084fc\",\"Top 10-5%\"],[\"Anomaly\",\"#f97316\",\"Top 5-1%\"],[\"Mythic\",\"#f87171\",\"Top 1%\"]];\nconst RT_B=[[\"Common\",\"#e7e5e4\",\">10% of rolls\"],[\"Uncommon\",\"#10b981\",\"1-10% of rolls\"],[\"Rare\",\"#60a5fa\",\"0.1-1% of rolls\"],[\"Epic\",\"#c084fc\",\"0.01-0.1% of rolls\"],[\"Anomaly\",\"#f97316\",\"0.001-0.01% of rolls\"],[\"Mythic\",\"#f87171\",\"<0.001% (1 in 100 000+)\"]];\nconst rtHtml=a=>a.map(([n,c,v])=>`<span class=\"n\" style=\"color:${c}\">${n}</span><span class=\"v\">${v}</span>`).join(\"\");\n$(\"rtNum\").innerHTML=rtHtml(RT_NUM);$(\"rtBadge\").innerHTML=rtHtml(RT_B);\n\n(async()=>{\n  let data={user:null};\n  try{data=await api(\"/api/me\")}catch(e){toast(e.message)}\n  $(\"calib\").style.display=\"none\";$(\"rollBtn\").disabled=false;\n  applyAccount(data);\n})();\n</script>\n</body>\n</html>\n";
const game = (() => { const module = { exports: {} }; new Function("module", GAME_SRC)(module); return module.exports; })();

const PORT = process.env.PORT || 3000;
const PROD = process.env.NODE_ENV === "production";
const SESSION_DAYS = 30;
const COOKIE = "ir_sess";
// Admins: usernames listed in the ADMIN_USERS environment variable, comma-separated (e.g. "PurpleLife,Bob")
const ADMINS = (process.env.ADMIN_USERS || "").split(",").map((x) => x.trim().toLowerCase()).filter(Boolean);
const isAdmin = (u) => !!u && ADMINS.includes(u.username.toLowerCase());
const COLORS = ["#111111", "#ef4444", "#f97316", "#eab308", "#22c55e", "#06b6d4", "#3b82f6", "#a855f7", "#ec4899"];

const app = express();
app.set("trust proxy", 1); // behind Render / Railway / etc.
app.disable("x-powered-by");
app.use(express.json({ limit: "10kb" }));
app.use((req, res, next) => {
  res.set("X-Content-Type-Options", "nosniff");
  res.set("Referrer-Policy", "same-origin");
  res.set("X-Frame-Options", "DENY");
  next();
});

// ---------- helpers ----------
const sha256 = (s) => crypto.createHash("sha256").update(s).digest("hex");
const userKey = (name) => "user:" + String(name).toLowerCase();
const dayKey = () => new Date().toISOString().slice(0, 10);
function weekKey() {
  const d = new Date();
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - day);
  const y = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  return t.getUTCFullYear() + "-W" + Math.ceil(((t - y) / 864e5 + 1) / 7);
}
const scoreOf = (n) => game.evaluate(n).reduce((a, x) => a + x.b.ep, 0);

function hashPassword(password, salt = crypto.randomBytes(16).toString("hex")) {
  return new Promise((resolve, reject) =>
    crypto.scrypt(password, salt, 64, { N: 16384, r: 8, p: 1 }, (err, key) => (err ? reject(err) : resolve({ salt, hash: key.toString("hex") })))
  );
}
async function checkPassword(password, user) {
  const { hash } = await hashPassword(password, user.salt);
  const a = Buffer.from(hash, "hex"), b = Buffer.from(user.hash, "hex");
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

function parseCookies(req) {
  const out = {};
  (req.headers.cookie || "").split(";").forEach((p) => {
    const i = p.indexOf("=");
    if (i > 0) out[p.slice(0, i).trim()] = decodeURIComponent(p.slice(i + 1).trim());
  });
  return out;
}
function setSessionCookie(req, res, token, maxAgeSec) {
  const parts = [`${COOKIE}=${token}`, "Path=/", "HttpOnly", "SameSite=Lax", `Max-Age=${maxAgeSec}`];
  if (req.secure || PROD) parts.push("Secure");
  res.set("Set-Cookie", parts.join("; "));
}
function createSession(req, res, username) {
  const token = crypto.randomBytes(32).toString("hex");
  store.set("sess:" + sha256(token), { u: username.toLowerCase(), exp: Date.now() + SESSION_DAYS * 864e5 });
  setSessionCookie(req, res, token, SESSION_DAYS * 86400);
}
function currentUser(req) {
  const token = parseCookies(req)[COOKIE];
  if (!token || !/^[a-f0-9]{64}$/.test(token)) return null;
  const s = store.get("sess:" + sha256(token));
  if (!s) return null;
  if (s.exp < Date.now()) { store.del("sess:" + sha256(token)); return null; }
  return store.get(userKey(s.u)) || null;
}

// Simple in-memory rate limiter
const hits = new Map();
function limited(key, max, windowMs) {
  const now = Date.now();
  const arr = (hits.get(key) || []).filter((t) => now - t < windowMs);
  arr.push(now);
  hits.set(key, arr);
  return arr.length > max;
}
setInterval(() => { const now = Date.now(); for (const [k, v] of hits) if (!v.some((t) => now - t < 3600e3)) hits.delete(k); }, 600e3).unref();

// Block cross-site POSTs (CSRF): browsers send Origin on POST
app.use("/api", (req, res, next) => {
  if (req.method !== "GET") {
    const origin = req.headers.origin;
    if (origin && new URL(origin).host !== req.headers.host) return res.status(403).json({ error: "Bad origin" });
  }
  next();
});

const publicProfile = (u) => ({ username: u.username, motto: u.motto || "", emoji: u.emoji || "", color: u.color || COLORS[0] });
const progress = (u) => ({ life: u.life || 0, rolls: u.rolls || 0, seen: u.seen || {}, top: u.top || [], last: u.last || null });

// ---------- account ----------
const USERNAME_RE = /^[A-Za-z0-9_]{3,16}$/;

app.post("/api/register", async (req, res) => {
  const { username, password } = req.body || {};
  if (limited("reg:" + req.ip, 5, 3600e3)) return res.status(429).json({ error: "Too many accounts created. Try again later." });
  if (typeof username !== "string" || !USERNAME_RE.test(username)) return res.status(400).json({ error: "Username: 3–16 letters, numbers or _" });
  if (typeof password !== "string" || password.length < 6 || password.length > 100) return res.status(400).json({ error: "Password: at least 6 characters" });
  if (store.get(userKey(username))) return res.status(409).json({ error: "That username is taken" });
  const { salt, hash } = await hashPassword(password);
  if (store.get(userKey(username))) return res.status(409).json({ error: "That username is taken" });
  const user = { username, salt, hash, created: Date.now(), motto: "", emoji: "", color: COLORS[0], life: 0, rolls: 0, seen: {}, top: [], likes: {} };
  store.set(userKey(username), user);
  createSession(req, res, username);
  res.json({ user: publicProfile(user), progress: progress(user), admin: isAdmin(user), theme: user.theme || null });
});

app.post("/api/login", async (req, res) => {
  const { username, password } = req.body || {};
  if (typeof username !== "string" || typeof password !== "string") return res.status(400).json({ error: "Missing username or password" });
  if (limited("login:" + req.ip, 20, 900e3) || limited("loginu:" + username.toLowerCase(), 10, 900e3))
    return res.status(429).json({ error: "Too many attempts. Wait 15 minutes." });
  const user = store.get(userKey(username));
  // Always run a hash so response time doesn't reveal whether the username exists
  const ok = user ? await checkPassword(password, user) : (await hashPassword(password), false);
  if (!ok) return res.status(401).json({ error: "Wrong username or password" });
  createSession(req, res, user.username);
  res.json({ user: publicProfile(user), progress: progress(user), admin: isAdmin(user), theme: user.theme || null });
});

app.post("/api/logout", (req, res) => {
  const token = parseCookies(req)[COOKIE];
  if (token && /^[a-f0-9]{64}$/.test(token)) store.del("sess:" + sha256(token));
  setSessionCookie(req, res, "", 0);
  res.json({ ok: true });
});

app.get("/api/me", (req, res) => {
  const u = currentUser(req);
  res.json(u ? { user: publicProfile(u), progress: progress(u), admin: isAdmin(u), theme: u.theme || null } : { user: null });
});

app.post("/api/profile", (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: "Log in first" });
  const { motto, emoji, color, theme } = req.body || {};
  const THEME_KEYS = ["white", "black", "gray", "red", "orange", "yellow", "green", "cyan", "blue", "purple", "pink", "brown"];
  if (theme && typeof theme === "object" && THEME_KEYS.includes(theme.k)) u.theme = { k: theme.k, mode: theme.mode === "dark" ? "dark" : "light" };
  if (typeof motto === "string") u.motto = motto.trim().replace(/\s+/g, " ").slice(0, 48);
  if (typeof emoji === "string") u.emoji = [...emoji.trim()].slice(0, 4).join("");
  if (COLORS.includes(color)) u.color = color;
  store.set(userKey(u.username), u);
  res.json({ user: publicProfile(u) });
});

app.post("/api/password", async (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: "Log in first" });
  const { current, next } = req.body || {};
  if (limited("pw:" + u.username.toLowerCase(), 10, 900e3)) return res.status(429).json({ error: "Too many attempts. Wait 15 minutes." });
  if (typeof current !== "string" || !(await checkPassword(current, u))) return res.status(401).json({ error: "Current password is wrong" });
  if (typeof next !== "string" || next.length < 6 || next.length > 100) return res.status(400).json({ error: "New password: at least 6 characters" });
  Object.assign(u, await hashPassword(next));
  store.set(userKey(u.username), u);
  // log out every other session
  for (const k of store.keys("sess:")) if (store.get(k).u === u.username.toLowerCase()) store.del(k);
  createSession(req, res, u.username);
  res.json({ ok: true });
});

// ---------- rolling (done on the server: no cheating) ----------
function secureNumber() {
  const r = crypto.randomInt(0, 100000000); // 1 in 100,000,000 steps
  if (r < 1) return 1000000;                // 1 in 100,000,000
  if (r < 5) return 0;                      // 1 in 25,000,000
  return 1 + crypto.randomInt(0, 999999);   // 1 .. 999,999
}

app.post("/api/roll", (req, res) => {
  const u = currentUser(req);
  const who = u ? "u:" + u.username.toLowerCase() : "ip:" + req.ip;
  if (limited("roll:" + who, 4, 1000)) return res.status(429).json({ error: "Slow down!" });
  const n = secureNumber();
  const ev = game.evaluate(n);
  const total = ev.reduce((a, x) => a + x.b.ep, 0);
  const result = { n, total, pct: game.topPct(total), badges: ev.map((x) => x.b.id) };
  if (!u) return res.json({ result, saved: false });

  const prevBest = u.top && u.top[0] ? u.top[0].total : 0;
  const fresh = [];
  u.seen = u.seen || {};
  for (const id of result.badges) { if (!u.seen[id]) fresh.push(id); u.seen[id] = (u.seen[id] || 0) + 1; }
  u.rolls = (u.rolls || 0) + 1;
  u.life = (u.life || 0) + total;
  u.top = [...(u.top || []), { n, total, pct: result.pct, badges: result.badges }].sort((a, b) => b.total - a.total).slice(0, 25);
  u.last = result;
  const tierName = game.TIERS.find((t) => result.pct <= t[0])[1];
  u.tiers = u.tiers || {};
  u.tiers[tierName] = (u.tiers[tierName] || 0) + 1;
  const dk = dayKey(), wk = weekKey();
  if (!u.day || u.day.key !== dk || total > u.day.total) u.day = { key: dk, n, total };
  if (!u.week || u.week.key !== wk || total > u.week.total) u.week = { key: wk, n, total };
  store.set(userKey(u.username), u);
  res.json({ result, saved: true, fresh, record: total > prevBest && u.rolls > 1, progress: progress(u) });
});

// ---------- player profile ----------
app.get("/api/player/:username", (req, res) => {
  const u = store.get(userKey(req.params.username));
  if (!u) return res.status(404).json({ error: "No such player" });
  const users = store.values("user:");
  const lower = u.username.toLowerCase();
  const likes = users.filter((o) => o.likes && o.likes[lower]).length;
  const bestTotal = u.top && u.top[0] ? u.top[0].total : -1;
  const rank = bestTotal < 0 ? null : 1 + users.filter((o) => o.top && o.top[0] && o.top[0].total > bestTotal).length;
  const seen = u.seen || {};
  const byRarity = {};
  for (const b of game.BADGES) {
    byRarity[b.rar] = byRarity[b.rar] || { found: 0, total: 0 };
    byRarity[b.rar].total++;
    if (seen[b.id]) byRarity[b.rar].found++;
  }
  const found = game.BADGES.filter((b) => seen[b.id]);
  const rarest = found.sort((a, b) => a.p - b.p).slice(0, 3).map((b) => b.id);
  const favorite = Object.entries(seen).filter(([id]) => { const b = game.BADGES.find((x) => x.id === id); return b && b.p < 0.1; })
    .sort((a, b) => b[1] - a[1])[0];
  const dk = dayKey(), wk = weekKey();
  res.json({
    ...publicProfile(u),
    created: u.created || null,
    rolls: u.rolls || 0,
    life: u.life || 0,
    likes,
    rank,
    players: users.length,
    top: (u.top || []).slice(0, 5).map((r) => ({ n: r.n, total: r.total, pct: r.pct })),
    today: u.day && u.day.key === dk ? { n: u.day.n, total: u.day.total } : null,
    week: u.week && u.week.key === wk ? { n: u.week.n, total: u.week.total } : null,
    badges: Object.keys(seen).length,
    badgesTotal: game.BADGES.length,
    byRarity,
    rarest,
    favorite: favorite ? { id: favorite[0], count: favorite[1] } : null,
    tiers: u.tiers || {},
  });
});

// ---------- leaderboard ----------
app.get("/api/leaderboard", (req, res) => {
  const view = ["day", "week", "all", "badges"].includes(req.query.view) ? req.query.view : "day";
  const me = currentUser(req);
  const users = store.values("user:");
  const likeCount = {};
  for (const u of users) for (const t in u.likes || {}) likeCount[t] = (likeCount[t] || 0) + 1;
  const dk = dayKey(), wk = weekKey();
  let rows = users.map((u) => {
    let pick = null;
    if (view === "day") pick = u.day && u.day.key === dk ? u.day : null;
    else if (view === "week") pick = u.week && u.week.key === wk ? u.week : null;
    else pick = u.top && u.top[0] ? u.top[0] : null;
    const badges = Object.keys(u.seen || {}).length;
    return { ...publicProfile(u), n: pick ? pick.n : null, total: pick ? pick.total : -1, badges,
      likes: likeCount[u.username.toLowerCase()] || 0, liked: !!(me && me.likes && me.likes[u.username.toLowerCase()]), me: !!(me && me.username === u.username) };
  });
  if (view === "badges") rows = rows.filter((r) => r.badges > 0).sort((a, b) => b.badges - a.badges || b.total - a.total);
  else rows = rows.filter((r) => r.n !== null).sort((a, b) => b.total - a.total);
  res.json({ view, total: game.BADGES.length, rows: rows.slice(0, 100) });
});

app.post("/api/like/:username", (req, res) => {
  const u = currentUser(req);
  if (!u) return res.status(401).json({ error: "Log in to like" });
  const target = String(req.params.username).toLowerCase();
  if (!store.get(userKey(target))) return res.status(404).json({ error: "No such player" });
  if (target === u.username.toLowerCase()) return res.status(400).json({ error: "You can't like yourself" });
  if (limited("like:" + u.username.toLowerCase(), 30, 60e3)) return res.status(429).json({ error: "Slow down!" });
  u.likes = u.likes || {};
  if (u.likes[target]) delete u.likes[target]; else u.likes[target] = true;
  store.set(userKey(u.username), u);
  res.json({ liked: !!u.likes[target] });
});

// ---------- admin panel ----------
function requireAdmin(req, res) {
  const u = currentUser(req);
  if (!isAdmin(u)) { res.status(403).json({ error: "Admins only" }); return null; }
  return u;
}
function sessionsOf(lower) { return store.keys("sess:").filter((k) => (store.get(k) || {}).u === lower); }

app.get("/api/admin/users", (req, res) => {
  if (!requireAdmin(req, res)) return;
  const q = String(req.query.q || "").toLowerCase().slice(0, 32);
  const rows = store.values("user:")
    .filter((u) => !q || u.username.toLowerCase().includes(q))
    .sort((a, b) => (b.created || 0) - (a.created || 0))
    .slice(0, 200)
    .map((u) => ({ username: u.username, rolls: u.rolls || 0, life: u.life || 0, best: u.top && u.top[0] ? u.top[0].n : null,
      badges: Object.keys(u.seen || {}).length, created: u.created || 0, admin: isAdmin(u), sessions: sessionsOf(u.username.toLowerCase()).length }));
  res.json({ rows, count: store.keys("user:").length });
});

app.post("/api/admin/rename", (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const { username, newName } = req.body || {};
  const u = store.get(userKey(username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (typeof newName !== "string" || !USERNAME_RE.test(newName)) return res.status(400).json({ error: "Username: 3–16 letters, numbers or _" });
  const oldL = u.username.toLowerCase(), newL = newName.toLowerCase();
  if (newL !== oldL && store.get(userKey(newName))) return res.status(409).json({ error: "That username is taken" });
  if (isAdmin(u) && newL !== oldL) return res.status(400).json({ error: "This is an admin account: change ADMIN_USERS on Render first, or only change the capitalization" });
  u.username = newName;
  if (newL !== oldL) {
    store.del(userKey(oldL));
    for (const k of sessionsOf(oldL)) store.set(k, { ...store.get(k), u: newL });
    for (const k of store.keys("user:")) {
      const o = store.get(k);
      if (o.likes && o.likes[oldL]) { delete o.likes[oldL]; o.likes[newL] = true; store.set(k, o); }
    }
  }
  store.set(userKey(newName), u);
  console.log(`[admin] ${admin.username} renamed ${oldL} -> ${newName}`);
  res.json({ ok: true });
});

app.post("/api/admin/password", async (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const { username, password } = req.body || {};
  const u = store.get(userKey(username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (typeof password !== "string" || password.length < 6 || password.length > 100) return res.status(400).json({ error: "Password: at least 6 characters" });
  Object.assign(u, await hashPassword(password));
  store.set(userKey(u.username), u);
  for (const k of sessionsOf(u.username.toLowerCase())) store.del(k); // log them out everywhere
  console.log(`[admin] ${admin.username} changed the password of ${u.username}`);
  res.json({ ok: true });
});

app.post("/api/admin/delete", (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const u = store.get(userKey((req.body || {}).username));
  if (!u) return res.status(404).json({ error: "No such player" });
  if (u.username.toLowerCase() === admin.username.toLowerCase()) return res.status(400).json({ error: "You can't delete your own account" });
  const l = u.username.toLowerCase();
  store.del(userKey(l));
  for (const k of sessionsOf(l)) store.del(k);
  for (const k of store.keys("user:")) { const o = store.get(k); if (o.likes && o.likes[l]) { delete o.likes[l]; store.set(k, o); } }
  console.log(`[admin] ${admin.username} deleted ${u.username}`);
  res.json({ ok: true });
});

app.post("/api/admin/reset", (req, res) => {
  const admin = requireAdmin(req, res); if (!admin) return;
  const u = store.get(userKey((req.body || {}).username));
  if (!u) return res.status(404).json({ error: "No such player" });
  Object.assign(u, { life: 0, rolls: 0, seen: {}, top: [], last: null, day: null, week: null });
  store.set(userKey(u.username), u);
  console.log(`[admin] ${admin.username} reset the stats of ${u.username}`);
  res.json({ ok: true });
});

// ---------- static files ----------
app.get("/game.js", (req, res) => res.type("application/javascript").send(GAME_SRC));
app.get(["/", "/index.html"], (req, res) => res.type("html").send(INDEX_HTML));

store.init().then(() => {
  app.listen(PORT, () => console.log(`InfiniRoll running on http://localhost:${PORT}`));
  console.log(ADMINS.length ? `[admin] Admins: ${ADMINS.join(", ")}` : "[admin] No admin set (add ADMIN_USERS in the environment variables)");
  const shutdown = () => store.flush().finally(() => process.exit(0));
  process.on("SIGTERM", shutdown);
  process.on("SIGINT", shutdown);
});
